uploadsController.uploadFile = async function (req, res, next) {
	const uploadedFile = req.files.files[0];
	let params;
	try {
		params = JSON.parse(req.body.params);
	} catch (e) {
		file.delete(uploadedFile.path);
		return next(new Error('[[error:invalid-json]]'));
	}

	try {
		if (typeof params.folder !== 'string') {
			throw new Error('[[error:invalid-path]]');
		}
		const uploadPath = path.resolve(nconf.get('upload_path'));
		const targetFolder = path.join(uploadPath, params.folder);
		const relativeFolder = path.relative(uploadPath, targetFolder);
		if (relativeFolder === '..' || relativeFolder.startsWith(`..${path.sep}`) || path.isAbsolute(relativeFolder)) {
			throw new Error('[[error:invalid-path]]');
		}
		let folderStat;
		try {
			folderStat = await fs.promises.stat(targetFolder);
		} catch (err) {
			if (err.code === 'ENOENT' || err.code === 'ENOTDIR') {
				throw new Error('[[error:invalid-path]]');
			}
			throw err;
		}
		if (!folderStat.isDirectory()) {
			throw new Error('[[error:invalid-path]]');
		}
		const data = await file.saveFileToLocal(uploadedFile.name, params.folder, uploadedFile.path);
		res.json([{ url: data.url }]);
	} catch (err) {
		next(err);
	} finally {
		file.delete(uploadedFile.path);
	}
};

